message.content:
{
  "html": "<div data-ui-unit="E1" class="e1-header">
  <h1 class="e1-title">멘토 찾기</h1>
  <div class="e1-tools">
    <button class="e1-tool-btn" disabled aria-label="알림">
      <img src="assets/reference/bell.svg" alt="알림" width="24" height="24">
    </button>
    <button class="e1-tool-btn" disabled aria-label="관심 멘토">
      <img src="assets/reference/heart.svg" alt="관심 멘토" width="24" height="24">
    </button>
    <button class="e1-tool-btn" disabled aria-label="프로필">
      <img src="assets/reference/user-round.svg" alt="프로필" width="24" height="24">
    </button>
  </div>
</div>",
  "css": ".e1-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 54px;
  width: 100%;
  padding: 8px 0;
}

.e1-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  margin: 0;
  white-space: nowrap;
}

.e1-tools {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}

.e1-tool-btn {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.e1-tool-btn img {
  display: block;
  width: 24px;
  height: 24px;
  opacity: 0.6;
}

@media (max-width: 360px) {
  .e1-title {
    font-size: 16px;
  }
  .e1-tools {
    gap: 12px;
  }
  .e1-tool-btn img {
    width: 20px;
    height: 20px;
  }
}"
}
